<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { goto } from '$app/navigation';
  import { RealtimeClient, type RealtimeStatus } from '$lib/realtime/client';
  import { TeacherApi, readableError, type ClassRoom, type ClosedQuestionView, type CsvPreview, type FileTask, type FileTaskView, type OpenQuestionView, type PendingApproval, type QuestionKind, type QuestionSummary, type ReferenceAnswer, type RosterStudent, type Template, type TemplateInput } from '$lib/teacher-api';
  const api = new TeacherApi();
  let state: 'checking' | 'first-run' | 'login' | 'teacher' = 'checking'; let notice = ''; let error = ''; let busy = false;
  let classes: readonly ClassRoom[] = []; let classCursor: string | undefined; let selectedClassId = ''; let className = ''; let csv = '姓名,學號\n'; let csvPreview: CsvPreview | undefined; let pending: readonly PendingApproval[] = []; let pendingCursor: string | undefined; let roster: readonly RosterStudent[] = []; let rosterCursor: string | undefined;
  let templates: readonly Template[] = []; let selectedTemplateId = ''; let kind: QuestionKind = 'single_choice'; let prompt = ''; let optionText = 'option-1 | 選項一\noption-2 | 選項二'; let reference = '';
  let questionId = ''; let questions: readonly QuestionSummary[] = []; let questionsCursor: string | undefined; let questionView: OpenQuestionView | ClosedQuestionView | undefined; let questionCursor: string | undefined;
  let fileTaskId = ''; let fileTasks: readonly FileTask[] = []; let fileTasksCursor: string | undefined; let fileTitle = ''; let fileDescription = ''; let fileDeadline = ''; let fileTaskView: FileTaskView | undefined; let password = '';
  let dangerDialog: HTMLDialogElement; let confirmButton: HTMLButtonElement; let dangerLabel = ''; let dangerDescription = ''; let dangerAction: (() => Promise<void>) | undefined; let returnFocus: HTMLElement | undefined;
  let realtime: RealtimeClient | undefined; let realtimeStatus: RealtimeStatus | undefined; let pollTimer: ReturnType<typeof setInterval> | undefined; let mounted = false; let dataGeneration = 0; let resyncing: Promise<void> | undefined; let resyncQueued = false;
  const selectedClass = (): ClassRoom | undefined => classes.find((item) => item.id === selectedClassId);
  const selectedTemplate = (): Template | undefined => templates.find((item) => item.id === selectedTemplateId);
  onMount(() => { mounted = true; void initialise(); return () => { mounted = false; dataGeneration += 1; realtime?.stop(); if (pollTimer !== undefined) clearInterval(pollTimer); }; });
  async function initialise(): Promise<void> { try { const health = await api.health(); if (health.reason === 'FIRST_RUN_SETUP_REQUIRED') { state = 'first-run'; return; } if (await api.restoreTeacher()) { await goto('/teacher'); return; } state = 'login'; } catch { state = 'login'; } }
  async function run(work: () => Promise<void>): Promise<void> { busy = true; error = ''; notice = ''; try { await work(); } catch (caught) { error = readableError(caught); } finally { busy = false; } }
  async function login(): Promise<void> { await run(async () => { await api.login(password); password = ''; await goto('/teacher'); }); }
  async function refreshClasses(expectedGeneration = dataGeneration): Promise<void> { const page = await api.classes(); if (!mounted || expectedGeneration !== dataGeneration) return; classes = page.items; classCursor = page.nextCursor; if (!classes.some((item) => item.id === selectedClassId)) selectedClassId = classes[0]?.id ?? ''; await refreshClassDetails(expectedGeneration); }
  async function refreshClassDetails(expectedGeneration = dataGeneration): Promise<void> { if (!selectedClassId) { roster = []; pending = []; questions = []; fileTasks = []; rosterCursor = pendingCursor = questionsCursor = fileTasksCursor = undefined; return; } const [nextRoster, nextPending, nextQuestions, nextFileTasks] = await Promise.all([api.roster(selectedClassId), api.pending(selectedClassId), api.questions(selectedClassId), api.fileTasks(selectedClassId)]); if (!mounted || expectedGeneration !== dataGeneration) return; roster = nextRoster.items; rosterCursor = nextRoster.nextCursor; pending = nextPending.items; pendingCursor = nextPending.nextCursor; questions = nextQuestions.items; questionsCursor = nextQuestions.nextCursor; fileTasks = nextFileTasks.items; fileTasksCursor = nextFileTasks.nextCursor; }
  async function moreClasses(): Promise<void> { if (classCursor === undefined) return; const page = await api.classes(classCursor); classes = [...classes, ...page.items]; classCursor = page.nextCursor; }
  async function moreRoster(): Promise<void> { if (rosterCursor === undefined) return; const page = await api.roster(selectedClassId, rosterCursor); roster = [...roster, ...page.items]; rosterCursor = page.nextCursor; }
  async function morePending(): Promise<void> { if (pendingCursor === undefined) return; const page = await api.pending(selectedClassId, pendingCursor); pending = [...pending, ...page.items]; pendingCursor = page.nextCursor; }
  async function moreQuestions(): Promise<void> { if (questionsCursor === undefined) return; const page = await api.questions(selectedClassId, questionsCursor); questions = [...questions, ...page.items]; questionsCursor = page.nextCursor; }
  async function moreFileTasks(): Promise<void> { if (fileTasksCursor === undefined) return; const page = await api.fileTasks(selectedClassId, fileTasksCursor); fileTasks = [...fileTasks, ...page.items]; fileTasksCursor = page.nextCursor; }
  async function refreshTemplates(): Promise<void> { templates = await api.templates(); }
  async function resyncTeacher(): Promise<void> {
    if (state !== 'teacher') return;
    if (resyncing !== undefined) { resyncQueued = true; return resyncing; }
    const expectedGeneration = dataGeneration;
    resyncing = (async () => {
      do {
        resyncQueued = false;
        await Promise.all([refreshClasses(expectedGeneration), refreshTemplates()]);
        if (!mounted || state !== 'teacher' || expectedGeneration !== dataGeneration) return;
        if (questionId) await readQuestion(questionCursor, expectedGeneration);
        if (fileTaskId) await readFileTask(expectedGeneration);
      } while (resyncQueued && mounted && state === 'teacher' && expectedGeneration === dataGeneration);
    })();
    try { await resyncing; } finally { resyncing = undefined; }
  }
  function startRealtime(): void {
    realtime?.stop();
    realtime = new RealtimeClient({ resources: ['roster', 'question', 'file-task', 'pending', 'submission'], teacherClassId: () => selectedClassId || undefined, resync: resyncTeacher, onStatus: (status) => { if (mounted) realtimeStatus = status; } });
    realtime.start();
    if (pollTimer !== undefined) clearInterval(pollTimer);
    pollTimer = setInterval(() => { if (!realtime?.isLive()) void resyncTeacher(); }, 15_000);
  }
  async function createClass(): Promise<void> { await run(async () => { const room = await api.createClass(className); className = ''; await refreshClasses(); selectedClassId = room.id; notice = `已建立「${room.name}」。`; }); }
  function requireClass(): boolean { if (selectedClassId) return true; error = '請先選擇或建立班級。'; return false; }
  function requireQuestion(): boolean { if (questionId) return true; error = '請先建立或輸入題目 ID。'; return false; }
  async function inspectCsv(): Promise<void> { if (!requireClass()) return; await run(async () => { csvPreview = await api.previewRoster(selectedClassId, csv); notice = '已完成 CSV 預覽；確認無誤後才匯入。'; }); }
  async function importCsv(): Promise<void> { if (!requireClass()) return; await run(async () => { const result = await api.importRoster(selectedClassId, csv); csvPreview = result; notice = result.issues.length === 0 ? `已匯入 ${result.rows.length} 位學生。` : '名單未匯入；請先修正標示的列。'; }); }
  async function readCsvFile(event: Event): Promise<void> { const input = event.currentTarget as HTMLInputElement; const file = input.files?.[0]; if (file === undefined) return; await run(async () => { csv = await file.text(); csvPreview = undefined; notice = `已讀取 ${file.name}，請先預覽再匯入。`; }); }
  async function approvePending(id: string): Promise<void> { await run(async () => { const result = await api.approvePending(id); await refreshClassDetails(); notice = `已核准 ${result.displayName}。`; }); }
  function parsedOptions(): readonly Readonly<{ id: string; label: string }>[] { return optionText.split('\n').map((line, index) => { const [first, ...rest] = line.split('|'); const maybeId = first ?? ''; const label = (rest.length > 0 ? rest.join('|') : maybeId).trim(); return { id: (rest.length > 0 ? maybeId : `option-${index + 1}`).trim(), label }; }).filter((option) => option.id.length > 0 && option.label.length > 0); }
  function questionInput(): TemplateInput { const options = kind === 'short_text' ? [] : parsedOptions(); const answer: ReferenceAnswer = kind === 'multiple_choice' ? reference.split(',').map((value) => value.trim()).filter(Boolean) : reference.trim() || null; return { kind, prompt, ...(kind === 'short_text' ? {} : { options }), referenceAnswer: answer }; }
  function useTemplate(template: Template): void { selectedTemplateId = template.id; kind = template.kind; prompt = template.prompt; optionText = template.options.map((option) => `${option.id} | ${option.label}`).join('\n'); reference = typeof template.referenceAnswer === 'string' ? template.referenceAnswer : template.referenceAnswer?.join(', ') ?? ''; }
  function newTemplate(): void { selectedTemplateId = ''; kind = 'single_choice'; prompt = ''; optionText = 'option-1 | 選項一\noption-2 | 選項二'; reference = ''; }
  async function saveTemplate(): Promise<void> { await run(async () => { const current = selectedTemplate(); const saved = current === undefined ? await api.createTemplate(questionInput()) : await api.updateTemplate(current.id, questionInput()); await refreshTemplates(); useTemplate(saved); notice = current === undefined ? '已新增題庫範本。' : '已更新題庫範本。'; }); }
  async function createDraft(): Promise<void> { if (!requireClass()) return; await run(async () => { const draft = selectedTemplateId.length > 0 ? await api.createDraft(selectedClassId, { templateId: selectedTemplateId }) : await api.createDraft(selectedClassId, { question: questionInput() }); questionId = draft.id; await refreshClassDetails(); notice = '已建立題目草稿；請確認後再開放。'; }); }
  async function openQuestion(): Promise<void> { if (!requireQuestion()) return; await run(async () => { await api.openQuestion(questionId); await readQuestion(); await refreshClassDetails(); notice = '題目已開放；僅顯示匿名彙總。'; }); }
  async function closeQuestion(): Promise<void> { if (!requireQuestion()) return; await run(async () => { await api.closeQuestion(questionId); questionCursor = undefined; await readQuestion(); await refreshClassDetails(); notice = '題目已關閉；現在可查看具名作答。'; }); }
  async function requestCloseQuestion(event: MouseEvent): Promise<void> { if (!requireQuestion()) return; await askDanger('關閉即時題', '關閉後學生不能再作答，且題目不可重新開放。請確認已完成收答。', closeQuestion, event); }
  async function readQuestion(cursor?: string, expectedGeneration = dataGeneration): Promise<void> { if (!requireQuestion()) return; const requestedId = questionId; const result = await api.question(requestedId, cursor); if (!mounted || expectedGeneration !== dataGeneration || requestedId !== questionId) return; questionCursor = cursor; questionView = result; }
  async function loadQuestion(cursor?: string): Promise<void> { await run(() => readQuestion(cursor)); }
  function toLocalInput(value: string): string { const date = new Date(value); return new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16); }
  function fileInput(): Readonly<{ title: string; description: string; deadlineAtUtc: string }> { return { title: fileTitle, description: fileDescription, deadlineAtUtc: new Date(fileDeadline).toISOString() }; }
  async function createFileTask(): Promise<void> { if (!requireClass()) return; await run(async () => { const task = await api.createFileTask(selectedClassId, fileInput()); fileTaskId = task.id; notice = '已建立檔案作業草稿。'; await readFileTask(); await refreshClassDetails(); }); }
  async function readFileTask(expectedGeneration = dataGeneration): Promise<void> { if (!requireClass() || !fileTaskId) throw new Error('請輸入班級與檔案作業 ID。'); const requestedClassId = selectedClassId; const requestedId = fileTaskId; const result = await api.fileTask(requestedClassId, requestedId); if (!mounted || expectedGeneration !== dataGeneration || requestedClassId !== selectedClassId || requestedId !== fileTaskId) return; fileTaskView = result; const task = result.task; fileTitle = task.title; fileDescription = task.description; fileDeadline = toLocalInput(task.deadlineAtUtc); }
  async function loadFileTask(): Promise<void> { await run(readFileTask); }
  async function updateFileTask(): Promise<void> { if (!requireClass() || !fileTaskId) return; await run(async () => { await api.updateFileTask(selectedClassId, fileTaskId, fileInput()); await readFileTask(); notice = '已更新檔案作業草稿。'; }); }
  async function openFileTask(): Promise<void> { if (!requireClass() || !fileTaskId) return; await run(async () => { await api.openFileTask(selectedClassId, fileTaskId); await readFileTask(); notice = '檔案作業已開放。'; }); }
  async function closeFileTask(): Promise<void> { if (!requireClass() || !fileTaskId) return; await run(async () => { await api.closeFileTask(selectedClassId, fileTaskId); await readFileTask(); notice = '檔案作業已關閉，可下載已交檔案。'; }); }
  async function requestCloseFileTask(event: MouseEvent): Promise<void> { if (!requireClass() || !fileTaskId) return; await askDanger('關閉檔案作業', '關閉後學生不能再上傳，且作業不可重新開放。請確認已完成收件。', closeFileTask, event); }
  async function askDanger(label: string, description: string, action: () => Promise<void>, event: MouseEvent): Promise<void> { dangerLabel = label; dangerDescription = description; dangerAction = action; returnFocus = event.currentTarget as HTMLElement; await tick(); dangerDialog.showModal(); confirmButton.focus(); }
  async function confirmDanger(): Promise<void> { dangerDialog.close(); const action = dangerAction; dangerAction = undefined; if (action !== undefined) await run(action); await tick(); returnFocus?.focus(); }
  function cancelDanger(): void { dangerAction = undefined; setTimeout(() => returnFocus?.focus()); }
</script>

<svelte:head><title>教師管理｜LAN 課堂平台</title><meta name="description" content="教師專用的班級、題目與檔案作業管理介面。" /></svelte:head>
{#if state === 'checking'}
  <main class="centered" aria-busy="true"><p>正在確認服務狀態…</p></main>
{:else if state === 'first-run'}
  <main class="centered" aria-labelledby="first-run-title"><section class="panel blocked"><h1 id="first-run-title">尚未完成教師首次設定</h1><p>為保護課堂資料，目前系統只提供健康狀態，教師登入與管理介面尚未啟用。</p><p>需要由系統管理員在本機完成首次密碼設定後重新啟動服務。此版本沒有可安全使用的首次設定 API，因此不會在網頁中蒐集或傳送密碼。</p></section></main>
{:else if state === 'login'}
  <main class="centered" aria-labelledby="login-title"><form class="panel login" on:submit|preventDefault={() => void login()}><h1 id="login-title">教師登入</h1><p>請使用共用教師密碼。登入後的安全權杖只保留在目前頁面，重新整理時請重新登入。</p><label for="password">教師密碼</label><input id="password" type="password" autocomplete="current-password" bind:value={password} required /><button class="primary" disabled={busy}>{busy ? '登入中…' : '登入'}</button>{#if error}<p class="error" role="alert">{error}</p>{/if}</form></main>
{:else}
  <main aria-labelledby="app-title">
    <header class="top"><div><p class="eyebrow">LAN CLASSROOM</p><h1 id="app-title">教師管理</h1></div><button on:click={() => void run(async () => { realtime?.stop(); realtime = undefined; dataGeneration += 1; if (pollTimer !== undefined) clearInterval(pollTimer); pollTimer = undefined; await api.logout(); state = 'login'; classes = []; templates = []; notice = '已登出。'; })}>登出</button></header>
    <div class="feedback" aria-live="polite" aria-atomic="true">{#if notice}<p class="notice">{notice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</div>
    {#if realtimeStatus === 'offline' || realtimeStatus === 'reconnecting'}<p class="muted">即時更新暫時中斷，畫面仍會定時重新確認。</p>{/if}
    <nav aria-label="教師功能"><a href="#classes">班級與名單</a><a href="#questions">題庫與即時題</a><a href="#files">檔案作業</a></nav>
    <section id="classes" aria-labelledby="classes-title"><div class="section-title"><h2 id="classes-title">班級與名單</h2><button on:click={() => void run(refreshClasses)} disabled={busy}>重新整理班級</button></div>
      <div class="grid two"><form class="panel" on:submit|preventDefault={() => void createClass()}><h3>建立班級</h3><label for="class-name">班級名稱</label><input id="class-name" bind:value={className} required maxlength="200" /><button class="primary" disabled={busy}>建立班級</button></form>
      <div class="panel"><h3>目前班級</h3><label for="class-picker">選擇班級</label><select id="class-picker" bind:value={selectedClassId} on:change={() => { realtime?.subscribeTeacherClass(); void run(refreshClassDetails); }}>{#each classes as room}<option value={room.id}>{room.name}</option>{/each}</select>{#if classCursor}<button on:click={() => void run(moreClasses)} disabled={busy}>載入更多班級</button>{/if}{#if selectedClass()}<p class="muted">請到「班級與已加入學生」管理或刪除班級。</p>{/if}</div></div>
      <div class="grid two"><section class="panel" aria-labelledby="csv-title"><h3 id="csv-title">名單 CSV 預覽與匯入</h3><p class="muted">標題列須為「姓名,學號」或「name,studentNumber」。先預覽，確認無錯誤再匯入。</p><label for="csv-file">從 CSV 檔讀取</label><input id="csv-file" type="file" accept=".csv,text/csv" on:change={(event) => void readCsvFile(event)} /><label for="csv">CSV 內容</label><textarea id="csv" rows="7" bind:value={csv} spellcheck="false"></textarea><div class="actions"><button type="button" on:click={() => void inspectCsv()} disabled={busy}>預覽</button><button type="button" class="primary" on:click={() => void importCsv()} disabled={busy}>確認匯入</button></div></section>
      <section class="panel" aria-labelledby="pending-title"><h3 id="pending-title">待審學生與名單</h3><button on:click={() => void run(refreshClassDetails)} disabled={busy || !selectedClassId}>重新整理</button>{#if pending.length === 0}<p class="muted">沒有待審申請。</p>{:else}<ul>{#each pending as request}<li>{request.displayName}（{request.studentNumber}）<button class="primary small" on:click={() => void approvePending(request.id)} disabled={busy}>核准</button></li>{/each}</ul>{/if}{#if pendingCursor}<button on:click={() => void run(morePending)} disabled={busy}>載入更多待審學生</button>{/if}{#if roster.length > 0}<p class="muted">已核准名單：{roster.map((student) => `${student.displayName}（${student.studentNumber}）`).join('、')}</p>{/if}{#if rosterCursor}<button on:click={() => void run(moreRoster)} disabled={busy}>載入更多已核准學生</button>{/if}</section></div>
      {#if csvPreview}<section class="panel" aria-labelledby="csv-result"><h3 id="csv-result">預覽結果</h3>{#if csvPreview.issues.length > 0}<ul class="issues">{#each csvPreview.issues as issue}<li>第 {issue.line} 列：{issue.message}</li>{/each}</ul>{:else}<p class="notice">資料格式正確，共 {csvPreview.rows.length} 筆。匯入仍會檢查既有學號與併發衝突。</p><div class="table-wrap"><table><thead><tr><th>姓名</th><th>學號</th></tr></thead><tbody>{#each csvPreview.rows as row}<tr><td>{row.displayName}</td><td>{row.rawStudentNumber}</td></tr>{/each}</tbody></table></div>{/if}</section>{/if}
    </section>
    <section id="questions" aria-labelledby="questions-title"><div class="section-title"><h2 id="questions-title">題庫與即時題</h2><button on:click={() => void run(refreshTemplates)} disabled={busy}>重新整理題庫</button></div>
      <div class="grid two"><section class="panel"><h3>題庫範本</h3><label for="template-select">選取既有範本</label><select id="template-select" bind:value={selectedTemplateId} on:change={() => { const template = selectedTemplate(); if (template !== undefined) useTemplate(template); }}><option value="">新增範本</option>{#each templates as template}<option value={template.id}>{template.prompt}</option>{/each}</select><button on:click={newTemplate}>清空為新範本</button>{@render QuestionForm()}<div class="actions"><button class="primary" on:click={() => void saveTemplate()} disabled={busy}>{selectedTemplateId ? '更新範本' : '儲存範本'}</button>{#if selectedTemplateId}<button class="danger" on:click={(event) => void askDanger('刪除題庫範本', '已建立的題目會保留其快照，但此範本將無法再使用。', async () => { await api.deleteTemplate(selectedTemplateId); newTemplate(); await refreshTemplates(); notice = '題庫範本已刪除。'; }, event)}>刪除範本</button>{/if}</div></section>
      <section class="panel"><h3>建立與控制即時題</h3><p class="muted">使用選取範本可建立不可受範本日後修改影響的題目快照；未選範本則用左側內容建立。</p><button class="primary" on:click={() => void createDraft()} disabled={busy}>建立草稿</button><label for="question-id">選擇題目</label><select id="question-id" bind:value={questionId}><option value="">請選擇題目</option>{#each questions as item}<option value={item.id}>{item.state}｜{item.prompt}</option>{/each}</select>{#if questionsCursor}<button on:click={() => void run(moreQuestions)} disabled={busy}>載入更多題目</button>{/if}<div class="actions"><button on:click={() => void loadQuestion()} disabled={busy}>讀取狀態</button><button class="primary" on:click={() => void openQuestion()} disabled={busy}>開放題目</button><button on:click={(event) => void requestCloseQuestion(event)} disabled={busy}>關閉題目</button></div><p class="muted">開放中只顯示匿名彙總；關閉後才顯示具名作答。參考答案只存在本教師畫面，絕不傳送至學生畫面。</p></section></div>
      {#if questionView}<section class="panel" aria-labelledby="question-status"><h3 id="question-status">題目狀態：{questionView.question.state}</h3><p>{questionView.question.prompt}</p>{#if 'aggregate' in questionView}<p class="notice">匿名作答：{questionView.aggregate.answeredStudentCount} / {questionView.aggregate.eligibleStudentCount}</p><ul>{#each Object.entries(questionView.aggregate.counts) as [optionId, count]}<li>{optionId}：{count}</li>{/each}{#if questionView.aggregate.shortTextResponseCount > 0}<li>短答回覆：{questionView.aggregate.shortTextResponseCount}</li>{/if}</ul>{:else}{@render ClosedAnswers(questionView)}{/if}</section>{/if}
    </section>
    <section id="files" aria-labelledby="files-title"><h2 id="files-title">檔案作業</h2><div class="grid two"><section class="panel"><h3>建立／編輯檔案作業</h3><label for="file-title">標題</label><input id="file-title" bind:value={fileTitle} maxlength="200" /><label for="file-description">說明</label><textarea id="file-description" bind:value={fileDescription} rows="4"></textarea><label for="file-deadline">截止時間</label><input id="file-deadline" type="datetime-local" bind:value={fileDeadline} /><div class="actions"><button class="primary" on:click={() => void createFileTask()} disabled={busy}>建立草稿</button><button on:click={() => void updateFileTask()} disabled={busy}>更新草稿</button></div></section>
      <section class="panel"><h3>作業狀態與交件</h3><label for="file-task-id">選擇檔案作業</label><select id="file-task-id" bind:value={fileTaskId}><option value="">請選擇作業</option>{#each fileTasks as item}<option value={item.id}>{item.state}｜{item.title}</option>{/each}</select>{#if fileTasksCursor}<button on:click={() => void run(moreFileTasks)} disabled={busy}>載入更多作業</button>{/if}<div class="actions"><button on:click={() => void loadFileTask()} disabled={busy}>讀取狀態</button><button class="primary" on:click={() => void openFileTask()} disabled={busy}>開放</button><button on:click={(event) => void requestCloseFileTask(event)} disabled={busy}>關閉</button></div>{#if fileTaskId}<button class="danger" on:click={(event) => void askDanger('刪除檔案作業', '只可在已逐筆刪除所有交件後刪除作業；此動作無法復原。', async () => { await api.deleteFileTask(selectedClassId, fileTaskId); fileTaskId = ''; fileTaskView = undefined; await refreshClassDetails(); notice = '檔案作業已刪除。'; }, event)}>刪除空白作業</button>{/if}</section></div>
      {#if fileTaskView}<section class="panel" aria-labelledby="file-status"><h3 id="file-status">{fileTaskView.task.title}（{fileTaskView.task.state}）</h3>{#if fileTaskView.completion}<p class="notice">已交：{fileTaskView.completion.submittedStudentCount} / {fileTaskView.completion.eligibleStudentCount}</p>{/if}{#if fileTaskView.submissions}<div class="table-wrap"><table><thead><tr><th>學生</th><th>檔名</th><th>大小</th><th>完成時間</th><th>操作</th></tr></thead><tbody>{#each fileTaskView.submissions as submission}<tr><td>{submission.displayName}（{submission.studentNumber}）</td><td>{submission.displayFilename}</td><td>{submission.byteLength} bytes</td><td>{submission.receivedCompleteAtUtc}</td><td><a class="button" href={api.downloadUrl(selectedClassId, fileTaskId, submission.studentId)}>下載</a><button class="danger small" on:click={(event) => void askDanger('刪除學生交件', `將永久刪除 ${submission.displayName} 的交件。`, async () => { await api.deleteSubmission(selectedClassId, fileTaskId, submission.studentId); await readFileTask(); notice = '交件已刪除。'; }, event)}>刪除</button></td></tr>{/each}</tbody></table></div>{/if}</section>{/if}
    </section>
  </main>
  <dialog bind:this={dangerDialog} aria-labelledby="danger-title" on:close={cancelDanger}><form method="dialog" class="dialog"><h2 id="danger-title">{dangerLabel}</h2><p>{dangerDescription}</p><p class="error">請確認你了解此操作無法復原。</p><div class="actions"><button value="cancel">取消</button><button bind:this={confirmButton} type="button" class="danger" on:click={() => void confirmDanger()}>確認執行</button></div></form></dialog>
{/if}
{#snippet QuestionForm()}<label for="kind">題型</label><select id="kind" bind:value={kind}><option value="single_choice">單選</option><option value="multiple_choice">複選</option><option value="short_text">短答</option></select><label for="prompt">題目</label><textarea id="prompt" bind:value={prompt} rows="3"></textarea>{#if kind !== 'short_text'}<label for="options">選項（每行「選項 ID | 文字」）</label><textarea id="options" bind:value={optionText} rows="4"></textarea>{/if}<label for="reference">參考答案（僅教師可見；複選以逗號分隔選項 ID）</label><input id="reference" bind:value={reference} />{/snippet}
{#snippet ClosedAnswers(view: ClosedQuestionView)}<p class="notice">已關閉：以下為具名作答，僅教師可見。</p><div class="table-wrap"><table><thead><tr><th>學生</th><th>學號</th><th>作答</th><th>操作</th></tr></thead><tbody>{#each view.answers as answer}<tr><td>{answer.displayName}</td><td>{answer.studentNumber}</td><td>{answer.answer === undefined ? '未作答' : JSON.stringify(answer.answer)}</td><td><button class="danger small" on:click={(event) => void askDanger('刪除作答', `將刪除 ${answer.displayName} 的作答紀錄。`, async () => { await api.deleteAnswer(questionId, answer.studentId); await readQuestion(questionCursor); notice = '作答已刪除。'; }, event)}>刪除</button></td></tr>{/each}</tbody></table></div>{#if view.nextCursor}<button on:click={() => void loadQuestion(view.nextCursor)}>載入下一頁</button>{/if}{/snippet}
<style>
  :global(*){box-sizing:border-box}:global(body){margin:0;color:#172033;background:#f5f7fb;font-family:system-ui,"Noto Sans TC",sans-serif;line-height:1.55}:global(button),:global(input),:global(select),:global(textarea){font:inherit}:global(button),.button{min-height:44px;padding:.55rem .9rem;border:1px solid #50627d;border-radius:.45rem;color:#172033;background:#fff;cursor:pointer;text-decoration:none}:global(button:hover),.button:hover{background:#e8eef8}:global(button:focus-visible),:global(a:focus-visible),:global(input:focus-visible),:global(select:focus-visible),:global(textarea:focus-visible){outline:3px solid #005fcc;outline-offset:2px}:global(button:disabled){cursor:wait;opacity:.6}main{max-width:1160px;margin:auto;padding:1.25rem}.centered{min-height:100vh;display:grid;place-items:center}.centered .panel{max-width:620px}.top,.section-title,.actions{display:flex;gap:.75rem;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;border-bottom:2px solid #d6deea;margin-bottom:1rem}h1,h2,h3{line-height:1.2}h2{margin-top:2.5rem}.eyebrow{color:#36527b;font-weight:700;letter-spacing:.08em;font-size:.8rem;margin-bottom:0}nav{display:flex;flex-wrap:wrap;gap:.75rem}nav a{color:#003f88;font-weight:700;min-height:44px;padding:.55rem .25rem}.grid{display:grid;gap:1rem;margin-block:1rem}.two{grid-template-columns:repeat(auto-fit,minmax(290px,1fr))}.panel{background:#fff;border:1px solid #c8d3e3;border-radius:.7rem;padding:1.15rem;box-shadow:0 1px 2px #17203312}.blocked{border-left:.4rem solid #a02b16}label{display:block;font-weight:700;margin-top:.8rem}input,select,textarea{width:100%;min-height:44px;border:1px solid #66758a;border-radius:.35rem;padding:.55rem;color:#172033;background:#fff}textarea{min-height:7rem;resize:vertical}.actions{margin-top:1rem}.primary{color:#fff;background:#064a9b;border-color:#064a9b}.primary:hover{background:#003b7c}.danger{color:#fff;background:#a22b18;border-color:#a22b18}.danger:hover{background:#81200f}.small{min-height:36px;padding:.35rem .6rem}.notice{color:#084a2c;background:#e4f5ea;border-left:.3rem solid #167341;padding:.6rem .75rem}.error,.issues{color:#7b1d10;background:#fff0ed;border-left:.3rem solid #b12b17;padding:.6rem .75rem}.muted{color:#45556d;font-size:.93rem}code{overflow-wrap:anywhere}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:.55rem;text-align:left;border-bottom:1px solid #d6deea;vertical-align:top}th{background:#eef3fa}dialog{max-width:540px;border:0;border-radius:.7rem;box-shadow:0 16px 50px #0008;padding:0}dialog::backdrop{background:#07132599}.dialog{padding:1.25rem}@media(prefers-reduced-motion:reduce){:global(*){scroll-behavior:auto!important;transition:none!important;animation:none!important}}
</style>
